// Extraire et formater les données du webhook
const data = $input.first().json.body || $input.first().json;

console.log('Données maintenance WhatsApp reçues:', JSON.stringify(data));

const maintenanceNumber = data.maintenance_number || data.maintenanceNumber || 'N/A';
const clientName = data.client_name || data.clientName || 'Client';
const phone = data.phone || '';
const kind = data.kind || 'technician';
const device = data.device || '';

// URL HTML du document (accessible via réseau Docker)
// Aligné sur le pattern facture/devis: URL interne nitek_app
const htmlUrl = `http://nitek_app:8000/api/maintenances/${data.maintenance_id}/print?kind=${encodeURIComponent(kind)}`;

// Construire le message caption
const caption = `Bonjour ${clientName || 'Client'},

🛠️ *MAINTENANCE ${maintenanceNumber}*
📄 Document: ${kind}
${device ? `💻 Appareil: ${device}\n` : ''}

Merci pour votre confiance.

Cordialement,
GeekTechnologie`;

return [{
  json: {
    phone: phone,
    htmlUrl: htmlUrl,
    filename: `Maintenance-${maintenanceNumber}-${kind}.pdf`,
    caption: caption
  }
}];
